python -c "
import json, zipfile
from pathlib import Path

def walk(node, depth=0, lines=None):
    if lines is None: lines = []
    if not isinstance(node, dict):
        return lines
    title = node.get('title') or node.get('topic') or ''
    if isinstance(title, dict):
        title = title.get('text') or str(title)
    # xmind zen format
    t = node.get('title')
    if t is None and 'rootTopic' in node:
        return walk(node['rootTopic'], depth, lines)
    if t is not None:
        lines.append(('  '*depth) + str(t).replace('\n',' / '))
    children = node.get('children') or {}
    attached = []
    if isinstance(children, dict):
        attached = children.get('attached') or children.get('topics') or []
        for k,v in children.items():
            if k not in ('attached','topics') and isinstance(v, list):
                for c in v:
                    walk(c, depth+1, lines)
    if isinstance(children, list):
        attached = children
    for c in attached:
        walk(c, depth+1, lines)
    # also topics
    for c in node.get('topics') or []:
        walk(c, depth+1, lines)
    return lines

p = Path(r'E:/project/清泉跨境系统（企业级）/清泉亚马逊驾驶舱仪表盘设计.xmind')
with zipfile.ZipFile(p) as z:
    data = json.loads(z.read('content.json').decode('utf-8'))

# dump structure keys
sheet = data[0]
print('sheet keys', list(sheet.keys()))
rt = sheet.get('rootTopic') or sheet
print('root keys', list(rt.keys())[:30])
lines = walk(sheet)
text = '\n'.join(lines)
Path(r'E:/project/清泉跨境系统（企业级）/_amz_dashboard_tree.txt').write_text(text, encoding='utf-8')
print('lines', len(lines))
print(text[:5000])
"

